const raw = $input.first().json;
const input = (raw && raw.body && typeof raw.body === 'object' && Object.keys(raw.body).length > 0) ? raw.body : raw;

const connectors = input.connectors || [
  { key: 'google_calendar', status: 'HEALTHY', level: 'READ_VERIFIED' },
  { key: 'whatsapp_business', status: 'HEALTHY', level: 'WEBHOOK_VERIFIED' },
  { key: 'okvet_assisted', status: 'HEALTHY', level: 'RECONCILIATION_VERIFIED' },
  { key: 'supabase_outbox', status: 'HEALTHY', level: 'END_TO_END_VERIFIED' },
  { key: 'wompi_payments', status: 'HEALTHY', level: 'READ_VERIFIED' },
  { key: 'dian_invoicing', status: 'HEALTHY', level: 'CONFIGURATION_FOUND' },
  { key: 'specialist_portal', status: 'HEALTHY', level: 'RECONCILIATION_VERIFIED' }
];

const discrepancies = [];
const expectedDifferences = [];
const humanTasks = [];
const safeRepairs = [];

const calDrift = Number(input.calendar_drift_events_count || 0);
const unacked = Number(input.unacknowledged_messages_count || 0);
const stalledOutbox = Number(input.outbox_stalled_events_count || 0);
const payDiff = Number(input.payment_discrepancies_count || 0);
const okvetConflicts = Number(input.okvet_conflicts_count || 0);
const revokedCaregiverAccess = Number(input.revoked_caregiver_access_count || 0);
const unconfirmedReferrals = Number(input.unconfirmed_referrals_count || 0);
const missingEvidenceCommitments = Number(input.missing_evidence_commitments_count || 0);
const asyncDelays = Number(input.expected_async_delays_count || 0);

if (asyncDelays > 0) {
  expectedDifferences.push({
    type: 'EXPECTED_ASYNCHRONOUS_DELAY',
    severity: 'INFORMATIONAL',
    detail: asyncDelays + ' webhooks en transito asincrono esperado (< 120s)',
    action: 'NO_ACTION_WAIT_TRANSIT'
  });
}

if (calDrift > 0) {
  discrepancies.push({
    type: 'STATUS_MISMATCH',
    entity_type: 'appointment',
    source_system: 'GOOGLE_CALENDAR',
    target_system: 'SUPABASE',
    severity: 'MEDIUM_OPERATIONAL',
    detail: 'Desfase de disponibilidad en Google Calendar: ' + calDrift + ' slots sin cita medica asociada',
    authoritative_system: 'SUPABASE',
    safe_repair_available: false,
    requires_human_approval: true
  });
  humanTasks.push({
    title: 'Revision de Desfase de Calendario',
    assigned_role: 'COORDINATOR',
    detail: 'Verificar si evento en Google Calendar corresponde a bloqueo personal o cita cancelada'
  });
}

if (unacked > 0) {
  discrepancies.push({
    type: 'UNCONFIRMED_EXTERNAL_ACTION',
    entity_type: 'whatsapp_message',
    source_system: 'WHATSAPP_META',
    target_system: 'SUPABASE',
    severity: 'LOW_OPERATIONAL',
    detail: unacked + ' mensajes enviados sin confirmacion de recibo de Meta (> 10 min)',
    authoritative_system: 'WHATSAPP_META',
    safe_repair_available: true,
    safe_repair_action: 'REQUERY_MESSAGE_STATUS_IDEMPOTENT'
  });
  safeRepairs.push({
    action: 'REQUERY_MESSAGE_STATUS_IDEMPOTENT',
    entity: 'whatsapp_message',
    count: unacked
  });
}

if (stalledOutbox > 0) {
  discrepancies.push({
    type: 'EVENT_NOT_PROCESSED',
    entity_type: 'outbox_event',
    source_system: 'SUPABASE',
    target_system: 'N8N_BUS',
    severity: 'HIGH_OPERATIONAL',
    detail: stalledOutbox + ' eventos en transactional_outbox atascados sin reclamar por worker (> 5 min)',
    authoritative_system: 'SUPABASE',
    safe_repair_available: true,
    safe_repair_action: 'RELEASE_EXPIRED_OUTBOX_LEASES'
  });
  safeRepairs.push({
    action: 'RELEASE_EXPIRED_OUTBOX_LEASES',
    entity: 'outbox_event',
    count: stalledOutbox
  });
}

if (payDiff > 0) {
  discrepancies.push({
    type: 'FINANCIAL_DISCREPANCY',
    entity_type: 'payment',
    source_system: 'WOMPI_OR_BANK',
    target_system: 'SUPABASE',
    severity: 'FINANCIAL_RISK',
    detail: payDiff + ' transacciones financieras con montos o estados no conciliados con extracto',
    authoritative_system: 'PAYMENT_PROVIDER',
    safe_repair_available: false,
    requires_human_approval: true
  });
  humanTasks.push({
    title: 'Conciliacion Bancaria Manual de Pagos',
    assigned_role: 'FINANCE_LEAD',
    detail: 'Cotejar comprobante contra extracto bancario oficial; prohibido auto-conciliar'
  });
}

if (okvetConflicts > 0) {
  discrepancies.push({
    type: 'OKVET_CONFLICT',
    entity_type: 'clinical_record',
    source_system: 'OKVET',
    target_system: 'SUPABASE',
    severity: 'CLINICAL_REVIEW_REQUIRED',
    detail: okvetConflicts + ' discrepancias entre registro administrativo y ficha oficial OKVET',
    authoritative_system: 'OKVET',
    safe_repair_available: false,
    requires_human_approval: true
  });
  humanTasks.push({
    title: 'Revision Medica de Expediente OKVET',
    assigned_role: 'DIRECTOR',
    detail: 'Verificacion clinica reservada al Dr. Luis Rios; prohibido alterar historia medica'
  });
}

if (revokedCaregiverAccess > 0) {
  discrepancies.push({
    type: 'AUTHORIZATION_REVOKED',
    entity_type: 'caregiver',
    source_system: 'SUPABASE',
    target_system: 'EXTERNAL_LINKS',
    severity: 'SECURITY_RISK',
    detail: revokedCaregiverAccess + ' cuidadores con permisos revocados que requieren invalidacion de tokens',
    authoritative_system: 'SUPABASE',
    safe_repair_available: true,
    safe_repair_action: 'PURGE_EXPIRED_OR_REVOKED_ACCESS_GRANTS'
  });
  safeRepairs.push({
    action: 'PURGE_EXPIRED_OR_REVOKED_ACCESS_GRANTS',
    entity: 'caregiver_grant',
    count: revokedCaregiverAccess
  });
}

if (unconfirmedReferrals > 0) {
  discrepancies.push({
    type: 'UNCONFIRMED_EXTERNAL_ACTION',
    entity_type: 'specialist_referral',
    source_system: 'EXTERNAL_SPECIALIST',
    target_system: 'SUPABASE',
    severity: 'HIGH_OPERATIONAL',
    detail: unconfirmedReferrals + ' remisiones seleccionadas por tutor sin confirmacion de radicado del especialista',
    authoritative_system: 'SUPABASE',
    safe_repair_available: false,
    requires_human_approval: true
  });
  humanTasks.push({
    title: 'Confirmacion Telefonica con Especialista Externo',
    assigned_role: 'COORDINATOR',
    detail: 'Contactar al especialista para obtener numero oficial de radicado'
  });
}

if (missingEvidenceCommitments > 0) {
  discrepancies.push({
    type: 'STATUS_MISMATCH',
    entity_type: 'post_visit_commitment',
    source_system: 'SUPABASE',
    target_system: 'STAFF_TASKS',
    severity: 'MEDIUM_OPERATIONAL',
    detail: missingEvidenceCommitments + ' compromisos marcados completados sin adjunto de evidencia requerida',
    authoritative_system: 'SUPABASE',
    safe_repair_available: false,
    requires_human_approval: true
  });
  humanTasks.push({
    title: 'Verificacion de Evidencia de Compromiso Post-Visita',
    assigned_role: 'COORDINATOR',
    detail: 'Exigir al veterinario o laboratorio el reporte antes de autorizar cierre de caso'
  });
}

const totalDiscrepancies = discrepancies.length;
const isClean = totalDiscrepancies === 0;

return {
  json: {
    reconciliation_run_id: input.run_id || '9b1deb4d-3b7d-4bad-9bdd-2b0d7b3dcb6d',
    scope: input.audit_scope || 'FULL_CROSS_SYSTEM_AUDIT',
    execution_mode: input.execution_mode || 'DRY_RUN',
    is_clean: isClean,
    discrepancy_count: totalDiscrepancies,
    expected_differences_count: expectedDifferences.length,
    human_tasks_created_count: humanTasks.length,
    safe_repairs_count: safeRepairs.length,
    discrepancies: discrepancies,
    expected_differences: expectedDifferences,
    human_tasks: humanTasks,
    safe_repairs: safeRepairs,
    connectors: connectors,
    reconciled_at: new Date().toISOString(),
    send_enabled: false,
    qa_mode: true
  }
};
